ROOT <- Sys.getenv("LEGIONELLA_ROOT"); if(!nzchar(ROOT)) stop("Set LEGIONELLA_ROOT before running this script.")
library(readr); library(dplyr); library(logistf)
a <- read_tsv(file.path(ROOT,"08_evidence_atlas","host_dependency_evidence_atlas.tsv.gz"),show_col_types=FALSE)
tr <- function(x) as.integer(toupper(as.character(x)) %in% c("TRUE","1","YES")); gc <- function(n) if(n %in% names(a)) suppressWarnings(as.numeric(a[[n]])) else rep(0,nrow(a))
d <- a %>% mutate(y=as.integer(grepl("^F",functional_tier)),lcv=tr(lcv_spatial_supported),ppi=tr(ppi_AB_flag),response=tr(stable_cross_cohort),nstudy=gc("expression_n_studies"),chronos=gc("u937_chronos_gene_effect"),common=tr(common_essential_flag)) %>% group_by(human_symbol) %>% summarise(across(c(y,lcv,ppi,response,nstudy,chronos,common),~median(.x,na.rm=TRUE)),.groups="drop") %>% mutate(across(everything(),~ifelse(is.finite(.x),.x,0)))
fit <- logistf(y ~ lcv + ppi + response + nstudy + chronos + common, data=d)
out <- data.frame(term=names(coef(fit)), beta=coef(fit), OR=exp(coef(fit)), p=fit$prob, lower=exp(fit$ci.lower), upper=exp(fit$ci.upper))
write_tsv(out,file.path(ROOT,"13_postfreeze_interpretation","joint_model_firth.tsv")); writeLines(c("Firth logistic regression sensitivity; no separation failure was reported by logistf.",capture.output(print(out))),file.path(ROOT,"13_postfreeze_interpretation","joint_model_firth_summary.txt")); print(out)
